using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ApiTool
{
    [McpServerTool, Description("Fetches data from an external API by path.")]
    public static async Task<string> FetchData(
        IHttpClientFactory httpClientFactory,
        [Description("The API endpoint path to query, e.g. \"users/1\".")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);

        // Pretty-print for readability in the tool response.
        using var doc = JsonDocument.Parse(json);
        return JsonSerializer.Serialize(doc, new JsonSerializerOptions { WriteIndented = true });
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerPromptType]
public static class SummarizePrompt
{
    [McpServerPrompt, Description("Generates a prompt that asks the model to summarize text.")]
    public static IList<McpServerPromptMessage> Summarize(
        [Description("The text to summarize.")] string text,
        [Description("Optional maximum number of sentences.")] string? maxSentences = null)
    {
        var instruction = maxSentences is not null
            ? $"Summarize the following text in at most {maxSentences} sentences."
            : "Summarize the following text concisely.";

        return
        [
            new(McpServerPromptMessageRole.User, new() { Text = $"{instruction}\n\n{text}" })
        ];
    }
}

